ALTER TABLE users ADD COLUMN IF NOT EXISTS provider TEXT NOT NULL DEFAULT 'entra';
ALTER TABLE users ADD COLUMN IF NOT EXISTS subject TEXT;
ALTER TABLE users ADD COLUMN IF NOT EXISTS is_active BOOLEAN NOT NULL DEFAULT TRUE;
CREATE UNIQUE INDEX IF NOT EXISTS uq_users_provider_subject ON users(provider, subject);

CREATE TABLE IF NOT EXISTS rbac_roles (id BIGSERIAL PRIMARY KEY, role_key TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rbac_permissions (id BIGSERIAL PRIMARY KEY, permission_key TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rbac_role_permissions (role_id BIGINT NOT NULL REFERENCES rbac_roles(id) ON DELETE CASCADE, permission_id BIGINT NOT NULL REFERENCES rbac_permissions(id) ON DELETE CASCADE, PRIMARY KEY (role_id, permission_id));
CREATE TABLE IF NOT EXISTS rbac_user_roles (user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id BIGINT NOT NULL REFERENCES rbac_roles(id) ON DELETE CASCADE, assigned_by TEXT, assigned_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY (user_id, role_id));
CREATE TABLE IF NOT EXISTS authorization_audit_events (id BIGSERIAL PRIMARY KEY, actor_subject TEXT NOT NULL, actor_provider TEXT NOT NULL, action TEXT NOT NULL, target_user_id TEXT, target_role_key TEXT, metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());

INSERT INTO rbac_roles (role_key, display_name) VALUES ('developer','Local Developer'),('author','Content Author'),('publisher','Content Publisher'),('administrator','Administrator') ON CONFLICT (role_key) DO NOTHING;
INSERT INTO rbac_permissions (permission_key, display_name) VALUES
 ('content:announcement-page:edit','Edit announcement page'),('content:announcement-page:publish','Publish announcement page'),('content:history:read','Read content history'),('content:restore','Restore content'),('leadership:edit','Edit leadership'),('leadership:publish','Publish leadership'),('journey:read','Read Journey'),('journey:manage','Manage Journey'),('rbac:users:read','Read users'),('rbac:users:manage','Manage user roles') ON CONFLICT (permission_key) DO NOTHING;
INSERT INTO rbac_role_permissions (role_id, permission_id) SELECT r.id,p.id FROM rbac_roles r CROSS JOIN rbac_permissions p WHERE r.role_key='administrator' ON CONFLICT DO NOTHING;
INSERT INTO users (id, external_id, email, display_name, role, provider, subject, is_active) VALUES
 ('00000000-0000-4000-8000-000000000001','dev-developer','developer@local.song-site','Local Developer','developer','development','dev-developer',TRUE),('00000000-0000-4000-8000-000000000002','dev-author','author@local.song-site','Local Author','author','development','dev-author',TRUE),('00000000-0000-4000-8000-000000000003','dev-publisher','publisher@local.song-site','Local Publisher','publisher','development','dev-publisher',TRUE),('00000000-0000-4000-8000-000000000004','dev-administrator','administrator@local.song-site','Local Administrator','administrator','development','dev-administrator',TRUE) ON CONFLICT (id) DO UPDATE SET provider=EXCLUDED.provider, subject=EXCLUDED.subject, is_active=EXCLUDED.is_active;
INSERT INTO rbac_user_roles (user_id, role_id) SELECT u.id,r.id FROM users u JOIN rbac_roles r ON r.role_key=u.role WHERE u.provider='development' ON CONFLICT DO NOTHING;